package com.petlis.service.impl;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.*;
import com.petlis.common.exception.BusinessException;import com.petlis.common.security.AccessService;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.transaction.support.TransactionSynchronizationManager;
import java.math.*;import java.security.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
/** Parameterizes Project/Pay.refund/refundQuery. No PHP clinical/fund reversal exists to copy. */
@Service @RequiredArgsConstructor
public class LegacyBankRefundService {
 private final FeatureStore store;private final AccessService access;private final LegacyBankPaymentExecutionService payments;private final ObjectMapper json;
 private static final String OP="LEGACY_BANK_REFUND";private static final SecureRandom RANDOM=new SecureRandom();
 public record Command(String paymentRequestKey,String amount,String reason,String requestKey){}
 public record Claimed(String token,Map<String,Object> parameters){}
 public boolean enabled(boolean query){return payments.allowed(query?"refundQueryEnabled":"refundEnabled");}
 @Transactional(rollbackFor=Exception.class) public Map<String,Object> create(Command c,String merchant){
  lock();gate(false);if(c==null||c.paymentRequestKey()==null||!validKey(c.paymentRequestKey())||!validKey(c.requestKey())||c.reason()==null||c.reason().length()>500||merchant==null||!merchant.matches("[A-Za-z0-9]{1,20}"))throw new BusinessException(400,"退款参数无效");
  BigInteger fen;try{if(c.amount()==null||!c.amount().matches("[0-9]{1,14}(\\.[0-9]{1,2})?"))throw new IllegalArgumentException();fen=new BigDecimal(c.amount()).movePointRight(2).toBigIntegerExact();if(fen.signum()<=0)throw new IllegalArgumentException();}catch(Exception e){throw new BusinessException(400,"退款金额须大于零，最多两位小数");}
  int actor=access.current().userId();String hash=hash(store.encode(c)+"\n"+merchant);var old=store.jdbc().queryForList("SELECT * FROM lin_order_idempotency WHERE user_id=? AND operation=? AND idempotency_key=? FOR UPDATE",actor,OP,c.requestKey());
  if(!old.isEmpty()){if(!hash.equals(old.get(0).get("request_hash")))throw new BusinessException(409,"请求键已用于其他退款内容");return receipt(old.get(0));}
  var pay=store.one("SELECT * FROM lin_order_idempotency WHERE user_id=? AND operation='LEGACY_BANK_PREPARE' AND idempotency_key=? FOR UPDATE",actor,c.paymentRequestKey());var original=body(pay);
  if(!"SUCCEEDED".equals(pay.get("status"))||!Objects.equals(merchant,original.get("merchant")))throw new BusinessException(409,"只能为已核实付款且商户一致的原单申请退款");
  String paymentId=original.get("orderId").toString();var mains=store.jdbc().queryForList("SELECT AliTradeId FROM lin_lb_payordermain WHERE OrderId=? FOR UPDATE",paymentId);if(mains.size()!=1||mains.get(0).get("AliTradeId").toString().isBlank())throw new BusinessException(409,"原支付收款记录待核对");
  BigInteger reserved=BigInteger.ZERO;for(var row:store.jdbc().queryForList("SELECT response_body FROM lin_order_idempotency WHERE operation=? AND status<>'CANCELLED' AND JSON_UNQUOTE(JSON_EXTRACT(response_body,'$.paymentOrderId'))=? FOR UPDATE",OP,paymentId))reserved=reserved.add(new BigInteger(body(row).get("amountFen").toString()));
  if(reserved.add(fen).compareTo(new BigInteger(original.get("amountFen").toString()))>0)throw new BusinessException(409,"退款申请合计超过原实付金额；结果不明的申请仍须保留额度");
  String refundId=number(merchant);var result=new LinkedHashMap<String,Object>();result.put("requestKey",c.requestKey());result.put("paymentRequestKey",c.paymentRequestKey());result.put("paymentOrderId",paymentId);result.put("refundOrderId",refundId);result.put("amount",new BigDecimal(fen).movePointLeft(2).setScale(2).toPlainString());result.put("amountFen",fen.toString());result.put("reason",c.reason());result.put("merchant",merchant);result.put("status","READY");
  store.insert("INSERT INTO lin_order_idempotency(user_id,hospital_id,operation,idempotency_key,request_hash,response_code,response_body,status,expires_at) VALUES(?,?,?,?,?,200,?,'READY',?)",actor,pay.get("hospital_id"),OP,c.requestKey(),hash,store.encode(result),LocalDateTime.now().plusDays(1));audit(actor,refundId,c.requestKey(),"READY");return exposed(result,"READY");
 }
 @Transactional(readOnly=true) public Map<String,Object> request(String key){readGate();return receipt(row(key,false));}
 @Transactional(readOnly=true) public Map<String,Object> list(int page,int size){readGate();var result=new LinkedHashMap<>(store.page("SELECT COUNT(*) FROM lin_order_idempotency WHERE user_id=? AND operation=?","SELECT * FROM lin_order_idempotency WHERE user_id=? AND operation=? ORDER BY id DESC",page,size,access.current().userId(),OP));@SuppressWarnings("unchecked")var rows=(List<Map<String,Object>>)result.get("items");result.put("items",rows.stream().map(this::receipt).toList());return result;}
 @Transactional(rollbackFor=Exception.class) public Map<String,Object> cancel(String key){lock();gate(false);var row=row(key,true);if("CANCELLED".equals(row.get("status")))return receipt(row);if(!"READY".equals(row.get("status")))throw new BusinessException(409,"已发送或结果不明的退款不能撤销额度，请先核对银行结果");var b=body(row);save(row,b,"CANCELLED");return exposed(b,"CANCELLED");}
 @Transactional(rollbackFor=Exception.class) public Claimed claim(String key,String merchant,boolean query){
  lock();gate(query);var row=row(key,true);var b=body(row);String state=row.get("status").toString();if(!Objects.equals(merchant,b.get("merchant")))throw new BusinessException(409,"退款商户不一致");
  if(!query&&!"READY".equals(state))throw new BusinessException(409,"退款已发送或结果待核对，禁止重复发送");if(query&&List.of("READY","CANCELLED").contains(state))throw new BusinessException(409,"该退款尚未发送银行");
  if(query&&"QUERYING".equals(state)&&(Boolean.TRUE.equals(row.get("lease_active"))||row.get("lease_active") instanceof Number active&&active.intValue()!=0))throw new BusinessException(409,"退款正在查询，请稍后刷新");
  String token=UUID.randomUUID().toString();b.put("executionToken",token);b.put(query?"queryAttempts":"sendAttempts",((Number)b.getOrDefault(query?"queryAttempts":"sendAttempts",0)).intValue()+1);b.put("status",query?"QUERYING":"SENDING");
  var p=new LinkedHashMap<String,Object>();p.put("merOrdrNo",query?number(merchant):b.get("refundOrderId"));p.put("oriMerOrdrNo",b.get("paymentOrderId"));p.put("oriTrxDt",LocalDateTime.now(ZoneId.of("Asia/Shanghai")).format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss")));if(!query)p.put("trxAmt",new BigInteger(b.get("amountFen").toString()));
  store.jdbc().update("UPDATE lin_order_idempotency SET response_body=?,status=?,locked_until=DATE_ADD(NOW(6),INTERVAL 70 SECOND) WHERE id=?",store.encode(b),b.get("status"),row.get("id"));audit(access.current().userId(),b.get("refundOrderId").toString(),key,b.get("status").toString());return new Claimed(token,Collections.unmodifiableMap(p));
 }
 @Transactional(rollbackFor=Exception.class) public void unknown(String key,String token){lock();var row=row(key,true);var b=body(row);if(Objects.equals(token,b.get("executionToken"))&&List.of("SENDING","QUERYING").contains(row.get("status").toString()))save(row,b,"UNKNOWN");}
 @Transactional(rollbackFor=Exception.class) public void finish(String key,String token,JsonNode verified){lock();var row=row(key,true);var b=body(row);if(!Objects.equals(token,b.get("executionToken"))||!List.of("SENDING","QUERYING").contains(row.get("status").toString()))return;b.put("bankResponse",verified);b.put("bankResponseText",store.encode(verified));save(row,b,"BANK_RESPONSE");}
 private Map<String,Object> row(String key,boolean locked){access.requireAdmin();if(!validKey(key))throw new BusinessException(400,"退款请求编号无效");return store.one("SELECT *,IF(locked_until>NOW(6),true,false) AS lease_active FROM lin_order_idempotency WHERE user_id=? AND operation=? AND idempotency_key=?"+(locked?" FOR UPDATE":""),access.current().userId(),OP,key);}
 private void readGate(){if(!payments.allowed("enabled"))throw new BusinessException(409,"原网银业务尚未开启");}
 private void gate(boolean query){if(!enabled(query))throw new BusinessException(409,"原网银退款操作尚未开启");}
 private void lock(){access.requireAdmin();if(!TransactionSynchronizationManager.isActualTransactionActive())throw new BusinessException(409,"退款操作需要事务");store.jdbc().queryForList("SELECT config_key FROM lin_operational_config WHERE config_key='legacy-bank-payments' AND scope_type='GLOBAL' AND scope_id=0 FOR UPDATE");}
 private Map<String,Object> receipt(Map<String,Object> row){return exposed(body(row),row.get("status").toString());}
 private Map<String,Object> exposed(Map<String,Object> body,String state){var result=new LinkedHashMap<>(body);result.remove("merchant");result.remove("executionToken");result.put("status",state);if(result.containsKey("bankResponse")&&!result.containsKey("bankResponseText"))result.put("bankResponseText",store.encode(result.get("bankResponse")));return result;}
 private Map<String,Object> body(Map<String,Object> row){try{return json.copy().enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS).readValue(row.get("response_body").toString(),new TypeReference<LinkedHashMap<String,Object>>(){});}catch(Exception e){throw new BusinessException(409,"退款记录异常，请人工核对");}}
 private void save(Map<String,Object> row,Map<String,Object> b,String status){b.put("status",status);store.jdbc().update("UPDATE lin_order_idempotency SET status=?,response_body=?,locked_until=NULL WHERE id=?",status,store.encode(b),row.get("id"));audit(((Number)row.get("user_id")).intValue(),b.get("refundOrderId").toString(),row.get("idempotency_key").toString(),status);}
 private void audit(int actor,String id,String key,String state){store.insert("INSERT INTO lin_audit_record(actor_user_id,action,resource_type,resource_id,request_id,after_json) VALUES(?,'LEGACY_BANK_REFUND','LEGACY_BANK_REFUND',?,?,?)",actor,id,key,store.encode(Map.of("status",state)));}
 private String number(String merchant){String stem=merchant+LocalDateTime.now(ZoneId.of("Asia/Shanghai")).format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss"));for(int i=0;i<20;i++){String id=stem+(100+RANDOM.nextInt(900));if(store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_lb_payordermain WHERE OrderId=?",Integer.class,id)==0&&store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_order_idempotency WHERE operation=? AND JSON_UNQUOTE(JSON_EXTRACT(response_body,'$.refundOrderId'))=?",Integer.class,OP,id)==0)return id;}throw new BusinessException(409,"退款请求编号冲突，请稍后重试");}
 private static boolean validKey(String key){return key!=null&&key.matches("[A-Za-z0-9_-]{1,128}");}
 private static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
